\title{The Bell Defect of a Finite Group Action, Counted Exactly}
\author{Aristotle}
\date{19 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let a finite group $G$ act on a finite set $X$ and let
$M_k=\sum_{g\in G}\card{X^g}^{\,k}$ be the $k$-th moment of its fixed-point family.
Burnside's lemma applied to the diagonal action on $X^k$ identifies $M_k$ with
$\card{G}\cdot\#(X^k/G)$, and assigning to each orbit of $k$-tuples its coincidence
pattern yields, for $k\le\card{X}$, the \emph{Bell floor} $M_k\ge B_k\card{G}$, where
$B_k$ is the $k$-th Bell number. We study the \emph{Bell defect} $D_k=M_k-B_k\card{G}$.
We prove the exact fibrewise formula $D_k=\card{G}\sum_P(m_P-1)$, where $m_P$ is the
number of orbits of $k$-tuples with coincidence pattern $P$, together with the
\emph{rank collapse} $m_P=t_r$ for every pattern of rank $r$, $t_r$ being the number of
$G$-orbits of injective $r$-tuples. This turns the defect into the Stirling transform
$D_k=\card{G}\sum_{r\le k}S(k,r)(t_r-1)$ of the fibre spectrum $(t_r)$, and gives
$D_k=0$ if and only if the action is $k$-transitive. Our main results are: a
block-graded transitivity criterion (all fibres over rank-$j$ patterns are singletons
iff the action is $j$-transitive); a moment--spectrum equivalence showing that the
spectrum is not finer than the moment family, though it is finer than any single
moment; sharp quantitative propagation $B_kD_2\le 2D_k$ with the extremal ray of the
relaxation shown to be unrealizable by any action; monotonicity $D_j\le D_k$; a
multiplicative constraint $\ff{t_1}{r}\le t_r$ with a quadratic lower bound for the
defect; and an arithmetic certificate: $\card{G}<\ff{\card{X}}{k}$ implies
$M_k\ge(B_k+1)\card{G}$.
\end{abstract}

\noindent\textbf{Keywords.} Burnside's lemma; Bell numbers; Stirling numbers of the
second kind; $k$-transitivity; set partitions; fixed-point moments; orbit counting.

\section{Introduction}

\subsection{Motivation}

Burnside's lemma, $\tfrac{1}{\card{G}}\sum_{g}\card{X^g}=\#(X/G)$, is the fundamental
tool of orbit enumeration. Its higher analogues, obtained by replacing $\card{X^g}$ with
$\card{X^g}^k$, have long been used ad hoc: the second moment computes the rank of a
permutation group (the number of orbits on ordered pairs), and higher moments compute
orbit counts of longer tuples. What has been missing is a structural account: an exact
identification of the arithmetic content of $M_k$, a canonical decomposition, and
quantitative inequalities relating different values of $k$.

This paper supplies such an account. The organizing principle is that a $k$-tuple
carries a group-invariant piece of combinatorial data --- the set partition of the index
set recording which coordinates coincide --- and that the resulting fibration of orbits
over partitions is governed entirely by a single integer sequence.

\subsection{Conventions}

Throughout, $G$ is a finite group acting on a finite set $X$ with $n=\card{X}$, and
$X^g=\{x\in X: g\cdot x=x\}$. The action on $X^k$, the set of functions
$\{1,\dots,k\}\to X$, is diagonal. We write $S(k,r)$ for the Stirling number of the
second kind, $B_k=\sum_{r=0}^{k}S(k,r)$ for the Bell number, and
$\ff{n}{r}=n(n-1)\cdots(n-r+1)$ for the falling factorial. Recall $B_0=B_1=1$, $B_2=2$,
$B_3=5$, $B_4=15$, $B_5=52$, $B_6=203$.

\section{Patterns and the orbit--pattern fibration}

\begin{definition}[Pattern]
A \emph{pattern} on $\{1,\dots,k\}$ is a set partition of $\{1,\dots,k\}$. In the
normalized form used below, a pattern is a map $P:\{1,\dots,k\}\to\{1,\dots,k\}$ with
$P(i)\le i$ and $P(P(i))=P(i)$ for all $i$: it sends each index to the least element of
its block. The image of $P$ is the set of \emph{block leaders}, and the \emph{rank}
$\rank(P)$ is the number of blocks. There are $S(k,r)$ patterns of rank $r$ and $B_k$
patterns in all.
\end{definition}

\begin{definition}[Kernel pattern]
For $f:\{1,\dots,k\}\to X$, the \emph{kernel pattern} $\Ker(f)$ is the pattern whose
blocks are the fibres of $f$: indices $i,j$ lie in a common block iff $f(i)=f(j)$.
\end{definition}

Two extreme cases recur: the \emph{discrete} pattern of rank $k$, whose blocks are
singletons --- the kernel pattern of exactly the injective tuples --- and, for each
$1\le j\le k$, the \emph{coarsening pattern}
\[
  \beta_{k,j}(i)=\min(i,j)\qquad(1\le i\le k),
\]
which keeps $1,\dots,j-1$ apart and merges $j,\dots,k$ into one block.

\begin{lemma}[Rank of the coarsening pattern]\label{lem:beta}
For $1\le j\le k$, $\beta_{k,j}$ is a pattern of rank exactly $j$.
\end{lemma}

\begin{proof}
Idempotence and $\beta_{k,j}(i)\le i$ follow from $\min(i,j)\le i$ and
$\min(\min(i,j),j)=\min(i,j)$. The image is $\{1,\dots,j\}$, of cardinality $j$.
\end{proof}

\begin{corollary}[No interior zeros in the Stirling triangle]\label{cor:nozeros}
For $1\le j\le k$ one has $S(k,j)\ge 1$.
\end{corollary}

This apparently trivial statement is what makes the block grading of
Section~\ref{sec:grading} non-vacuous: each graded piece is inhabited, so a statement
quantified over patterns of a given rank has content.

\begin{proposition}[Boundary of the Stirling triangle]\label{prop:boundary}
For $k\ge 1$: $S(k,k)=1$, $S(k,1)=1$, and $S(k,0)=0$.
\end{proposition}

\begin{proof}
If $\rank(P)=k$ then every index is a leader, so $P(i)=i$ for all $i$ and $P$ is
discrete; conversely the discrete pattern has rank $k$. If $\rank(P)=1$ then, since $1$
is always a leader ($P(1)\le 1$ forces $P(1)=1$), the unique leader is $1$ and
$P\equiv 1$. If $\rank(P)=0$ the leader set is empty, contradicting that $P(1)=1$ is a
leader.
\end{proof}

\begin{corollary}[Bell tail]\label{cor:tail}
For $k\ge1$, $\sum_{r=2}^{k}S(k,r)=B_k-1$, and every tail $\sum_{r=j}^{k}S(k,r)$ with
$j\le k$ is at least $1$. In particular $B_k\ge2$ for $k\ge2$.
\end{corollary}

\subsection{The orbit--pattern map and the Bell floor}

Since group elements act injectively, $\Ker(g\cdot f)=\Ker(f)$, so the kernel pattern
descends to orbits.

\begin{definition}
The \emph{orbit--pattern map} is $\pi:X^k/G\to\{\text{patterns on }\{1,\dots,k\}\}$,
$\pi([f])=\Ker(f)$. For a pattern $P$, its \emph{fibre multiplicity} is
$m_P=\#\pi^{-1}(P)$.
\end{definition}

\begin{proposition}[Surjectivity]\label{prop:surj}
If $k\le\card{X}$ then $\pi$ is surjective.
\end{proposition}

\begin{proof}
Given $P$ of rank $r\le k\le\card{X}$, choose $r$ distinct points of $X$ and send each
block of $P$ to a distinct one of them.
\end{proof}

\begin{theorem}[Bell floor]\label{thm:floor}
For $k\le\card{X}$,
\[
  \#(X^k/G)\ \ge\ B_k,\qquad \sum_{g\in G}\card{X^g}^{\,k}\ \ge\ B_k\card{G}.
\]
\end{theorem}

\begin{proof}
The first inequality is surjectivity of $\pi$ onto a set of size $B_k$. For the second,
$\card{X^g}^k=\#\{f\in X^k: g\cdot f=f\}$, since $g$ fixes a tuple iff it fixes each
coordinate; Burnside's lemma for the diagonal action gives
$\sum_g\card{X^g}^k=\card{G}\cdot\#(X^k/G)$.
\end{proof}

\begin{definition}[Bell defect]
$D_k=D_k(G,X)=\sum_{g\in G}\card{X^g}^{\,k}-B_k\card{G}$.
\end{definition}

By Theorem~\ref{thm:floor} this is a nonnegative integer for $k\le\card{X}$; and
$D_0=0$ always.

\begin{theorem}[Exact fibrewise formula]\label{thm:fibrewise}
For $k\le\card{X}$,
\[
  \sum_{g\in G}\card{X^g}^{\,k}
  =\Bigl(B_k+\sum_{P}(m_P-1)\Bigr)\card{G},
  \qquad\text{i.e.}\qquad
  D_k=\card{G}\sum_{P}(m_P-1),
\]
the sums running over all $B_k$ patterns on $\{1,\dots,k\}$.
\end{theorem}

\begin{proof}
Partitioning $X^k/G$ into fibres of $\pi$ gives $\#(X^k/G)=\sum_P m_P=B_k+\sum_P(m_P-1)$,
all $m_P\ge1$ by Proposition~\ref{prop:surj}. Multiply by $\card{G}$ and apply Burnside.
\end{proof}

\section{The fibre spectrum and the Stirling expansion}

\begin{definition}[Fibre spectrum]
For $r\ge0$ let $t_r=t_r(G,X)$ be the number of $G$-orbits of injective $r$-tuples
$\{1,\dots,r\}\hookrightarrow X$. The sequence $(t_0,t_1,\dots)$ is the \emph{fibre
spectrum} of the action.
\end{definition}

Immediately $t_0=1$, and $t_1=\#(X/G)$ is Burnside's orbit count; in spectral form
Burnside's lemma reads $t_1\card{G}=\sum_g\card{X^g}$.

\begin{theorem}[Rank collapse]\label{thm:collapse}
For every pattern $P$ on $\{1,\dots,k\}$ with $\rank(P)=r$, one has $m_P=t_r$.
\end{theorem}

\begin{proof}[Proof sketch]
A tuple $f$ with $\Ker(f)=P$ is uniquely determined by its restriction to the set of
block leaders, an injective $r$-tuple; conversely every injective $r$-tuple extends
uniquely along $P$ to a tuple with kernel pattern $P$. This bijection commutes with the
coordinatewise $G$-action, hence descends to orbit sets.
\end{proof}

\begin{corollary}[Stirling expansion]\label{cor:stirling}
For $k\le\card{X}$,
\[
  \#(X^k/G)=\sum_{r=0}^{k}S(k,r)\,t_r,
  \qquad
  D_k=\card{G}\sum_{r=0}^{k}S(k,r)\,(t_r-1).
\]
\end{corollary}

Two sanity checks: taking $G$ trivial gives $t_r=\ff{n}{r}$ and the classical identity
$n^k=\sum_r S(k,r)\ff{n}{r}$; taking $G$ to act $k$-transitively gives $t_r=1$ for
$r\le k$ and $D_k=0$.

\begin{proposition}[Monotonicity of the spectrum]\label{prop:specmono}
For $r\le s\le\card{X}$, $t_r\le t_s$.
\end{proposition}

\begin{proof}[Proof sketch]
Truncating an injective $s$-tuple to its first $r$ coordinates is a $G$-equivariant
surjection from injective $s$-tuples onto injective $r$-tuples, hence induces a
surjection of orbit sets.
\end{proof}

\begin{theorem}[Vanishing criterion]\label{thm:vanish}
For $k\le\card{X}$, $D_k=0$ if and only if the action is $k$-transitive.
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:stirling} and $t_r\ge1$, $D_k=0$ iff $t_r=1$ for all $r\le k$ with
$S(k,r)>0$; by Corollary~\ref{cor:nozeros} and Proposition~\ref{prop:boundary} those $r$
are exactly $1,\dots,k$. Now $t_k=1$ says precisely that the injective $k$-tuples form
one orbit, and $t_k=1$ forces $t_r=1$ for $r\le k$ by
Proposition~\ref{prop:specmono}.
\end{proof}

\section{The block grading}\label{sec:grading}

\begin{theorem}[Block-graded transitivity criterion]\label{thm:graded}
Let $1\le j\le k\le\card{X}$. Then every fibre over a pattern of rank $j$ is a singleton
if and only if the action is $j$-transitive:
\[
  \bigl(\forall P \text{ with }\rank(P)=j:\ m_P=1\bigr)
  \iff \text{the action is } j\text{-transitive}.
\]
\end{theorem}

\begin{proof}
($\Rightarrow$) The coarsening pattern $\beta_{k,j}$ has rank $j$
(Lemma~\ref{lem:beta}), so $m_{\beta_{k,j}}=1$; by rank collapse
(Theorem~\ref{thm:collapse}) $t_j=1$, which is $j$-transitivity. ($\Leftarrow$) If
$t_j=1$ then every rank-$j$ pattern has $m_P=t_j=1$.
\end{proof}

\begin{corollary}[Nesting]
Let $1\le i\le j\le k\le\card{X}$. If every fibre over a rank-$j$ pattern is a singleton,
so is every fibre over a rank-$i$ pattern.
\end{corollary}

\begin{proof}
The hypothesis gives $t_j=1$; Proposition~\ref{prop:specmono} and $t_i\ge1$ give
$t_i=1$; apply Theorem~\ref{thm:graded} in reverse.
\end{proof}

Thus the level-$k$ tuple data, graded by block number, resolves the whole transitivity
hierarchy below $k$ --- something no single moment does.

\subsection{Is the spectrum a finer invariant than the moments?}

\begin{theorem}[Moment--spectrum equivalence]\label{thm:equiv}
Let $G$ act on $X$ and $H$ act on $Y$, with $\card{G}=\card{H}$, and let $k\ge0$. Then
\[
  \Bigl(\forall j\le k:\ \sum_{g\in G}\card{X^g}^{\,j}=\sum_{h\in H}\card{Y^h}^{\,j}\Bigr)
  \iff
  \Bigl(\forall r\le k:\ t_r(G,X)=t_r(H,Y)\Bigr).
\]
\end{theorem}

\begin{proof}
($\Leftarrow$) Immediate from Corollary~\ref{cor:stirling} read forwards.
($\Rightarrow$) Strong induction on $r$. Assume $t_s(G,X)=t_s(H,Y)$ for $s<r\le k$. The
Stirling expansions of the $r$-th moments give
$\card{G}\sum_{s\le r}S(r,s)t_s(G,X)=\card{H}\sum_{s\le r}S(r,s)t_s(H,Y)$; cancelling
$\card{G}=\card{H}>0$ and subtracting the equal partial sums over $s<r$ leaves
$S(r,r)t_r(G,X)=S(r,r)t_r(H,Y)$ with $S(r,r)=1$.
\end{proof}

Structurally, the Stirling matrix $(S(j,r))_{j,r\le k}$ is lower unitriangular, hence
invertible over $\mathbb{Z}$: the spectrum contains no information the moment family
lacks. What it contains is the same information \emph{graded}, and it is the grading
(Theorem~\ref{thm:graded}) that is useful.

\begin{theorem}[A single moment is strictly coarser]\label{thm:sep}
There exist two actions of groups of the same order with equal second moments and
different fibre spectra. Let $C_4$ be cyclic of order $4$. The regular action of $C_4$ on
itself has $\card{X^g}=4$ for $g=1$ and $0$ otherwise, hence $\sum_g\card{X^g}^2=16$ and
$t_1=1$; the trivial action of $C_4$ on a two-element set has $\card{X^g}=2$ for all
four elements, hence $\sum_g\card{X^g}^2=4\cdot4=16$ and $t_1=2$.
\end{theorem}

Consistently with Theorem~\ref{thm:equiv}, the \emph{first} moments do separate this
pair: $4$ versus $8$.

\section{Quantitative propagation of the defect}

\begin{lemma}[Upper bound at a level]\label{lem:upper}
For $j\le\card{X}$, $D_j\le B_j(t_j-1)\card{G}$.
\end{lemma}

\begin{proof}
In $D_j=\card{G}\sum_{r\le j}S(j,r)(t_r-1)$ bound $t_r-1\le t_j-1$
(Proposition~\ref{prop:specmono}) and use $\sum_r S(j,r)=B_j$.
\end{proof}

\begin{lemma}[Lower bound from a lower level]\label{lem:lower}
For $j\le k\le\card{X}$,
$\bigl(\sum_{r=j}^{k}S(k,r)\bigr)(t_j-1)\card{G}\le D_k$.
\end{lemma}

\begin{theorem}[Propagation]\label{thm:prop}
For $j\le k\le\card{X}$,
$\bigl(\sum_{r=j}^{k}S(k,r)\bigr)D_j\le B_j D_k$.
\end{theorem}

\begin{proof}
Multiply Lemma~\ref{lem:upper} by the Stirling tail and apply Lemma~\ref{lem:lower}.
\end{proof}

\begin{corollary}
For $2\le k\le\card{X}$, $(B_k-1)D_2\le 2D_k$; in particular $D_2>0$ implies $D_k>0$, so
$k$-transitivity for some $k\ge2$ implies $2$-transitivity.
\end{corollary}

\begin{theorem}[Sharp propagation constant]\label{thm:sharp}
For $2\le k\le\card{X}$, $\ B_k\, D_2\ \le\ 2\,D_k$.
\end{theorem}

\begin{proof}
Write $a=t_1-1$, $b=t_2-1$; then $a\le b$ by Proposition~\ref{prop:specmono}. Using
$S(k,0)=0$, $S(k,1)=1$, $\sum_{r\ge2}S(k,r)=B_k-1$ and $t_r\ge t_2$ for $r\ge2$,
\[
  D_2=(a+b)\card{G},\qquad D_k\ge\bigl(a+(B_k-1)b\bigr)\card{G}.
\]
It suffices that $B_k(a+b)\le 2(a+(B_k-1)b)$, i.e.\ $(B_k-2)a\le(B_k-2)b$, which holds
since $a\le b$ and $B_k\ge2$.
\end{proof}

\begin{proposition}[Equality on the constant ray]
If $t_1=t_2=\cdots=t_k$ and $2\le k\le\card{X}$, then $2D_k=B_kD_2$.
\end{proposition}

\begin{proof}
With $x=t_1-1$, $D_2=2x\card{G}$ and $D_k=x\card{G}\sum_{r=1}^{k}S(k,r)=xB_k\card{G}$.
\end{proof}

Thus $B_k/2$ is optimal for the linear relaxation in which $(t_r)$ is an arbitrary
nondecreasing sequence: the ray $t_1=\cdots=t_k$ is extremal for
$\min\sum_r S(k,r)x_r$ subject to $x_1+x_2=1$, $x_1\le x_2\le\cdots$. That ray is
nevertheless fictitious.

\begin{lemma}[Two point orbits force three pair orbits]\label{lem:three}
If $\card{X}\ge3$ and $t_1=2$, then $t_2\ge3$.
\end{lemma}

\begin{proof}[Proof sketch]
Let $O_1,O_2$ be the two point orbits. Sending an orbit of injective pairs to the ordered
pair of point orbits of its coordinates is well defined; $(O_1,O_2)$ and $(O_2,O_1)$ are
both attained, giving two orbits. Since $\card{X}\ge3$, one $O_i$ has at least two
points, and an injective pair inside it gives a third orbit.
\end{proof}

\begin{lemma}\label{lem:t1t2}
If $\card{X}\ge3$ and $t_1=t_2$, then $t_1=1$.
\end{lemma}

\begin{proof}
By Theorem~\ref{thm:ff} below, $t_1(t_1-1)\le t_2=t_1$, so $t_1\le2$. If $t_1=2$ then
$t_2\ge3>t_1$ by Lemma~\ref{lem:three}, a contradiction.
\end{proof}

\begin{theorem}[The extremal ray is not realized]\label{thm:ray}
Let $3\le k\le\card{X}$ and suppose $t_1=t_2=\cdots=t_k$. Then $D_2=0$.
\end{theorem}

\begin{proof}
$k\ge3$ gives $\card{X}\ge3$, so Lemma~\ref{lem:t1t2} yields $t_1=1$, hence $t_2=1$ and
$D_2=\card{G}((t_1-1)+(t_2-1))=0$.
\end{proof}

Consequently, for genuinely non-$2$-transitive actions the true propagation constant
$\inf\{2D_k/D_2\}$ is strictly greater than $B_k$.

\section{Multiplicative constraints on the spectrum}

\begin{theorem}[Falling-factorial bound]\label{thm:ff}
For all $r\ge0$, $\ \ff{t_1}{r}=t_1(t_1-1)\cdots(t_1-r+1)\ \le\ t_r$.
\end{theorem}

\begin{proof}[Proof sketch]
Choose an ordered $r$-tuple of pairwise distinct point orbits --- there are $\ff{t_1}{r}$
of them --- and pick one point from each; the resulting $r$-tuple is injective. Two such
tuples lie in the same $G$-orbit only if they induce the same ordered tuple of point
orbits, since the orbit of a coordinate is $G$-invariant. Hence the assignment is
injective.
\end{proof}

\begin{corollary}
$t_1^2\le t_2+t_1$, i.e.\ $t_1(t_1-1)\le t_2$: an action with many point orbits has
quadratically many orbits of pairs.
\end{corollary}

\begin{theorem}[Quadratic lower bound for the defect]
For $2\le k\le\card{X}$,
\[
  D_k\ \ge\ \Bigl[(t_1-1)+(B_k-1)\bigl(t_1(t_1-1)-1\bigr)\Bigr]\card{G}.
\]
\end{theorem}

\begin{proposition}
For $\card{X}\ge2$, $D_2=\bigl((t_1-1)+(t_2-1)\bigr)\card{G}$.
\end{proposition}

\section{Monotonicity in the tuple length}

\begin{theorem}[Stirling columns are monotone]\label{thm:colmono}
For $1\le j\le k$ and every $s$, $S(j,s)\le S(k,s)$.
\end{theorem}

\begin{proof}
Given a pattern $p$ of $\{1,\dots,j\}$, let $\hat p$ be the pattern of $\{1,\dots,k\}$
with $\hat p(i)=p(i)$ for $i\le j$ and $\hat p(i)=1$ for $i>j$: every new coordinate
joins the block of $1$. Since $j\ge1$, the index $1$ is already a leader of $p$, so the
leader set is unchanged and $\rank(\hat p)=\rank(p)$. The map is injective, as $p$ is
recovered by restriction.
\end{proof}

The hypothesis $j\ge1$ is necessary: $S(0,0)=1>0=S(k,0)$ for $k\ge1$.

\begin{theorem}[The defect is monotone]
For $j\le k\le\card{X}$, $D_j\le D_k$; hence $D_j>0$ implies $D_k>0$.
\end{theorem}

\begin{proof}
For $j=0$, $D_0=0$. For $j\ge1$,
\[
  D_j=\card{G}\!\!\sum_{s\le j}\!S(j,s)(t_s-1)
  \le \card{G}\!\!\sum_{s\le j}\!S(k,s)(t_s-1)
  \le \card{G}\!\!\sum_{s\le k}\!S(k,s)(t_s-1)=D_k,
\]
by Theorem~\ref{thm:colmono} and nonnegativity of the omitted terms.
\end{proof}

\section{Arithmetic certificates}

\begin{theorem}[Order bound]\label{thm:order}
If the action is $k$-transitive with $k\le\card{X}$, then $\ff{\card{X}}{k}$ divides
$\card{G}$; in particular $\ff{\card{X}}{k}\le\card{G}$.
\end{theorem}

\begin{proof}
Fix an injective $k$-tuple $u$. Translation preserves injectivity, and $k$-transitivity
says the orbit of $u$ is the whole set of injective $k$-tuples, of cardinality
$\ff{\card{X}}{k}$. By orbit--stabiliser this orbit length divides $\card{G}$.
\end{proof}

\begin{corollary}[Strict violation of the Bell floor]
Let $k\le\card{X}$ and $\card{G}<\ff{\card{X}}{k}$. Then $t_k\ge2$, hence
$\#(X^k/G)\ge B_k+1$ and $\sum_{g\in G}\card{X^g}^{\,k}\ge(B_k+1)\card{G}$.
\end{corollary}

\section{Algorithms}

\textbf{Algorithm A (Fibre spectrum).} For each $r\le k$, enumerate injective
$r$-tuples, maintaining a set of visited tuples; for each unvisited tuple compute its
$G$-orbit by applying every group element, mark all members visited, and increment a
counter. Cost $O(\card{G}\cdot\ff{n}{r}\cdot r)$.

\smallskip\noindent
\textbf{Algorithm B (Bell defect, two ways).} Direct: compute $\card{X^g}$ for each $g$
and form $\sum_g\card{X^g}^k-B_k\card{G}$, in $O(\card{G}n)$ time. Spectral: compute the
Stirling row by $S(k,r)=r\,S(k-1,r)+S(k-1,r-1)$ in $O(k^2)$ time, then
$D_k=\card{G}\sum_r S(k,r)(t_r-1)$. Agreement of the two is a strong consistency check.

\smallskip\noindent
\textbf{Algorithm C (Graded transitivity profile).} For $j=1,\dots,k$ report
``$j$-transitive'' iff $t_j=1$. By Theorem~\ref{thm:graded} this is equivalent to testing
whether every fibre over a rank-$j$ pattern is a singleton, which can also be done by
enumerating orbits of $k$-tuples and bucketing them by kernel pattern, at cost
$O(\card{G}n^k k)$.

\smallskip\noindent
\textbf{Algorithm D (Certificate search).} Given $\card{G}$ and $n$, report a certificate
of $D_k>0$ whenever $\card{G}<\ff{n}{k}$, at cost $O(k)$ arithmetic operations and no
group computation.

\section{Worked examples}

\begin{center}
\begin{tabular}{lccccccc}
\toprule
action & $\card{G}$ & $\card{X}$ & $(t_0,\dots)$ & $D_1$ & $D_2$ & $D_3$ & $D_4$\\
\midrule
$S_4$ on $4$ points & $24$ & $4$ & $(1,1,1,1,1)$ & $0$ & $0$ & $0$ & $0$\\
$A_4$ on $4$ points & $12$ & $4$ & $(1,1,1,2,2)$ & $0$ & $0$ & $12$ & $84$\\
$C_4$ regular & $4$ & $4$ & $(1,1,3,6,6)$ & $0$ & $8$ & $44$ & $196$\\
$V_4$ regular & $4$ & $4$ & $(1,1,3,6,6)$ & $0$ & $8$ & $44$ & $196$\\
trivial group on $3$ points & $1$ & $3$ & $(1,3,6,6)$ & $2$ & $7$ & $22$ & ---\\
\bottomrule
\end{tabular}
\end{center}

For $A_4$: $t_3=2$, so the action is $2$- but not $3$-transitive, exactly as the graded
criterion predicts; $D_3=12\cdot S(3,3)(2-1)=12$ matches $M_3-B_3\card{G}=72-60=12$. For
$C_4$: $D_3=4(S(3,2)\cdot2+S(3,3)\cdot5)=4(6+5)=44$, and directly $M_3=64$,
$B_3\card{G}=20$. The propagation bound at $k=4$ for $C_4$ reads
$B_4D_2=15\cdot8=120\le 2D_4=392$, necessarily strict by Theorem~\ref{thm:ray}. Note that
$C_4$ and $V_4$ share a spectrum: these are invariants of the orbit structure on tuples,
not of the group.

\section{Discussion}

The theory buys three things. \emph{Exactness}: $D_k$ is an integer counting extra orbits
per coincidence pattern, vanishing precisely at $k$-transitivity. \emph{Gradedness}:
because multiplicities depend only on the block number, level-$k$ data splits into $k$
independent tests, one per level of the transitivity hierarchy. \emph{Rigidity}: the whole
apparatus is a Stirling transform, so moving between moments and spectrum is a
unitriangular change of basis.

Theorem~\ref{thm:equiv} is a genuine negative result: refining a moment into a vector of
multiplicities creates no information, because the refinement is invertible. Any
separation theorem for the spectrum must therefore concern a single moment
(Theorem~\ref{thm:sep}) or actions of groups of different orders. Likewise
Theorem~\ref{thm:ray} warns that optimizing over the cone defined only by monotonicity
overshoots; Theorem~\ref{thm:ff} is the first nonlinear correction.

Specializing $k=1$ recovers Burnside's lemma; specializing to the trivial group recovers
$n^k=\sum_r S(k,r)\ff{n}{r}$, so the Stirling expansion is an equivariant deformation of
that identity with falling factorials replaced by orbit counts. Theorem~\ref{thm:order} is
the standard divisibility constraint on multiply transitive groups, recovered as a
statement about the top of the spectrum.

\section{Future directions}

\begin{conjecture}[The true propagation constant]
Let $c_k^{\mathrm{grp}}=\inf\{2D_k/D_2\}$ over all finite actions with $2\le k\le\card{X}$
and $D_2>0$. Then $c_k^{\mathrm{grp}}>B_k$, and the infimum is attained by the trivial
action on $k$ points. Minimizing $\sum_r S(k,r)(t_r-1)$ subject to monotonicity and
$\ff{t_1}{r}\le t_r$ is a finite optimization for each $k$.
\end{conjecture}

\begin{conjecture}[A full multiplicative hierarchy]
For $r+s\le\card{X}$ the spectrum satisfies $t_{r+s}\ge t_r(t_s-r)$, and more precisely
$t_{r+s}$ is at least $t_r$ times the number of orbits of injective $s$-tuples avoiding a
fixed $r$-set. Theorem~\ref{thm:ff} is the case $s=1$, iterated.
\end{conjecture}

\begin{conjecture}[Realizability]
Characterize the nondecreasing integer sequences $(t_r)_{r\le k}$ with $t_0=1$ arising as
fibre spectra of finite actions on $n\ge k$ points. Monotonicity, the falling-factorial
bound, and $t_k\ge\ff{n}{k}/\card{G}$ are necessary; a complete characterization is open
even for $k=3$.
\end{conjecture}

Beyond a single action, dropping the equal-order hypothesis of
Theorem~\ref{thm:equiv}, or comparing pairs of actions of the same group, should produce a
richer separation theory in which the graded criterion plays the role of a fine invariant.
Finally, since $B_k$ grows superexponentially, Theorem~\ref{thm:sharp} says a single unit
of $2$-defect is amplified enormously with $k$; making the growth rate of $D_k$ into an
asymptotic invariant --- a ``transitivity entropy''
$\lim_k \frac1k\log(D_k/\card{G})$ --- appears tractable.

\section*{Appendix: the identity in one line}

For a finite group $G$ acting on a finite set $X$ with $k\le\card{X}$:
\[
  \sum_{g\in G}\card{X^g}^{\,k}
  =\Bigl(B_k+\sum_{P}(m_P-1)\Bigr)\card{G}
  =\Bigl(\sum_{r=0}^{k}S(k,r)\,t_r\Bigr)\card{G},
\]
with $m_P=t_{\rank P}$, $t_r$ the number of orbits of injective $r$-tuples, and equality
with the Bell floor $B_k\card{G}$ exactly when the action is $k$-transitive.

