"""Algorithm A: computation of the fibre spectrum of a finite permutation action.

The fibre spectrum (t_0, t_1, ..., t_k) of a group G acting on an n-element set X is
defined by t_r = number of G-orbits of injective r-tuples of points.  Because the
multiplicity of every coincidence pattern with r blocks equals t_r (the rank collapse),
this single sequence determines every moment sum_g |X^g|^j for j <= k, via the Stirling
expansion.
"""

from __future__ import annotations

from itertools import permutations
from typing import List, Sequence, Set, Tuple

Perm = Tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    """(p . q)(i) = p(q(i))."""
    return tuple(p[q[i]] for i in range(len(q)))


def generate_group(n: int, generators: Sequence[Perm]) -> List[Perm]:
    """Breadth-first closure of the generators inside the symmetric group on n points.

    Cost: O(|G| * |generators| * n) time.
    """
    identity: Perm = tuple(range(n))
    seen = {identity}
    frontier = [identity]
    while frontier:
        new_frontier: List[Perm] = []
        for element in frontier:
            for g in generators:
                candidate = compose(g, element)
                if candidate not in seen:
                    seen.add(candidate)
                    new_frontier.append(candidate)
        frontier = new_frontier
    return sorted(seen)


def inj_orbits(group: Sequence[Perm], n: int, r: int) -> int:
    """t_r: the number of G-orbits of injective r-tuples.

    Cost: O(|G| * n^{underline r} * r) time, O(n^{underline r}) space.
    """
    if r > n:
        return 0
    if r == 0:
        return 1
    visited: Set[Tuple[int, ...]] = set()
    count = 0
    for t in permutations(range(n), r):
        if t in visited:
            continue
        count += 1
        for g in group:
            visited.add(tuple(g[x] for x in t))
    return count


def fibre_spectrum(group: Sequence[Perm], n: int, k: int) -> List[int]:
    """The full spectrum (t_0, ..., t_k)."""
    return [inj_orbits(group, n, r) for r in range(k + 1)]


def transitivity_degree(group: Sequence[Perm], n: int) -> int:
    """The largest j with t_j = 1, i.e. the degree of transitivity of the action."""
    degree = 0
    for j in range(1, n + 1):
        if inj_orbits(group, n, j) == 1:
            degree = j
        else:
            break
    return degree


if __name__ == "__main__":
    s4 = generate_group(4, [(1, 0, 2, 3), (1, 2, 3, 0)])
    a4 = [g for g in s4 if sum(1 for i in range(4) for j in range(i)
                               if g[j] > g[i]) % 2 == 0]
    c4 = generate_group(4, [(1, 2, 3, 0)])
    for name, group in [("S4", s4), ("A4", a4), ("C4 regular", c4)]:
        print(f"{name:>12}: |G| = {len(group):>2}, spectrum = "
              f"{fibre_spectrum(group, 4, 4)}, "
              f"transitivity degree = {transitivity_degree(group, 4)}")

"""Algorithm B: the Bell defect, computed two independent ways.

Direct route:    D_k = sum_g |X^g|^k - B_k*|G|,  a single pass over the group.
Spectral route:  D_k = |G| * sum_{r<=k} S(k,r) * (t_r - 1),  the Stirling transform of
                 the fibre spectrum.

Agreement of the two routes is the sharpest available consistency check on the whole
theory: the left-hand side is an analytic-looking moment, the right-hand side is pure
partition combinatorics.  The Stirling row costs O(k^2) by the recurrence
S(k,r) = r*S(k-1,r) + S(k-1,r-1); the direct route costs O(|G|*n).
"""

from __future__ import annotations

from itertools import permutations
from typing import List, Sequence, Set, Tuple

Perm = Tuple[int, ...]


def stirling_row(k: int) -> List[int]:
    """[S(k,0), ..., S(k,k)] via the Pascal-type recurrence.  Cost O(k^2)."""
    row = [1] + [0] * k          # k = 0
    for i in range(1, k + 1):
        new = [0] * (k + 1)
        for r in range(1, i + 1):
            new[r] = r * row[r] + row[r - 1]
        row = new
    return row[: k + 1]


def bell_number(k: int) -> int:
    """B_k = sum_r S(k,r)."""
    return sum(stirling_row(k))


def fixed_points(p: Perm) -> int:
    return sum(1 for i, v in enumerate(p) if i == v)


def moment(group: Sequence[Perm], k: int) -> int:
    """M_k = sum_g |X^g|^k.  Cost O(|G|*n)."""
    return sum(fixed_points(g) ** k for g in group)


def inj_orbits(group: Sequence[Perm], n: int, r: int) -> int:
    if r > n:
        return 0
    if r == 0:
        return 1
    visited: Set[Tuple[int, ...]] = set()
    count = 0
    for t in permutations(range(n), r):
        if t in visited:
            continue
        count += 1
        for g in group:
            visited.add(tuple(g[x] for x in t))
    return count


def bell_defect_direct(group: Sequence[Perm], k: int) -> int:
    """D_k = M_k - B_k*|G|."""
    return moment(group, k) - bell_number(k) * len(group)


def bell_defect_spectral(group: Sequence[Perm], n: int, k: int) -> int:
    """D_k = |G| * sum_r S(k,r)*(t_r - 1)."""
    row = stirling_row(k)
    return len(group) * sum(row[r] * (inj_orbits(group, n, r) - 1)
                            for r in range(k + 1))


def cross_check(group: Sequence[Perm], n: int, kmax: int) -> List[Tuple[int, int, int]]:
    """Return (k, direct, spectral) for k = 1..kmax, asserting agreement."""
    out: List[Tuple[int, int, int]] = []
    for k in range(1, kmax + 1):
        a = bell_defect_direct(group, k)
        b = bell_defect_spectral(group, n, k)
        assert a == b, f"defect mismatch at k={k}: {a} vs {b}"
        assert a >= 0, "Bell floor violated"
        out.append((k, a, b))
    return out


if __name__ == "__main__":
    dihedral = [(0, 1, 2, 3), (1, 2, 3, 0), (2, 3, 0, 1), (3, 0, 1, 2),
                (0, 3, 2, 1), (1, 0, 3, 2), (2, 1, 0, 3), (3, 2, 1, 0)]
    print("dihedral group of order 8 acting on the 4 vertices of a square")
    for k, direct, spectral in cross_check(dihedral, 4, 4):
        print(f"  k = {k}:  M_k = {moment(dihedral, k):>4},  "
              f"B_k|G| = {bell_number(k) * 8:>4},  D_k = {direct:>4}  "
              f"(spectral route: {spectral})")
